glassmorphism_system.css_base:
.link-btn {
  background-color: var(--bio-card-bg);
  border: 1px solid var(--bio-card-border);
  border-radius: 50px;
  box-shadow: var(--bio-card-shadow);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}
.link-btn:hover {
  background-color: var(--bio-card-hover-bg);
  box-shadow: var(--bio-card-hover-shadow);
  border-color: var(--bio-primary);
  transform: translateY(-4px) scale(1.02);
}

blobs_animados.css:
.background-blobs {
  position: fixed; top: 0; left: 0;
  width: 100vw; height: 100vh;
  overflow: hidden; z-index: -1; pointer-events: none;
}
.blob {
  position: absolute; border-radius: 50%;
  filter: blur(80px); opacity: 0.6;
  animation: blob-float 20s infinite alternate ease-in-out;
}
.blob-1 {
  width: 400px; height: 400px;
  background: var(--bio-secondary);
  top: -100px; left: -100px;
  animation-delay: 0s;
}
.blob-2 {
  width: 300px; height: 300px;
  background: var(--bio-primary);
  bottom: -50px; right: -50px;
  animation-delay: -5s;
}
[data-bs-theme="dark"] .blob { opacity: 0.3; }

@keyframes blob-float {
  0% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(150px, 100px) scale(1.2); }
  100% { transform: translate(50px, 200px) scale(0.9); }
}

profile_gradient_ring.css:
.profile-img-wrapper {
  width: 120px; height: 120px;
  padding: 4px;
  border-radius: 50%;
  background: linear-gradient(45deg, var(--bio-primary), var(--bio-secondary));
  animation: pulse-ring 3s infinite cubic-bezier(0.215, 0.61, 0.355, 1);
}
.profile-img {
  width: 100%; height: 100%;
  border: 4px solid var(--bio-bg);
  border-radius: 50%;
  object-fit: cover;
  background-color: var(--bio-bg);
  transition: border-color 0.4s ease;
}
@keyframes pulse-ring {
  0% { box-shadow: 0 0 0 0 rgba(139, 92, 246, 0.5); }
  70% { box-shadow: 0 0 0 15px rgba(139, 92, 246, 0); }
  100% { box-shadow: 0 0 0 0 rgba(139, 92, 246, 0); }
}

fadein_escalonado_backwards.css:
.animate-item { animation: fadeInUp 0.6s ease backwards; position: relative; z-index: 10; }
header.animate-item { animation-delay: 0.1s; }
main.animate-item { animation-delay: 0.2s; }
footer .animate-item { animation-delay: 0.3s; }

.links-container .link-btn { animation: fadeInUp 0.5s ease backwards; }
.links-container .link-btn:nth-child(1) { animation-delay: 0.2s; }
.links-container .link-btn:nth-child(2) { animation-delay: 0.3s; }
.links-container .link-btn:nth-child(3) { animation-delay: 0.4s; }
.links-container .link-btn:nth-child(4) { animation-delay: 0.5s; }
.links-container .link-btn:nth-child(5) { animation-delay: 0.6s; }

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

icones_auto_deteccao.javascript:
const socialLinks = document.querySelectorAll('.social-icon-btn');
socialLinks.forEach(link => {
  const url = link.href.toLowerCase();
  const icon = link.querySelector('i');
  if (!icon) return;

  if (url.includes('instagram.com'))          icon.className = 'bi bi-instagram';
  else if (url.includes('twitter.com') || url.includes('x.com')) icon.className = 'bi bi-twitter-x';
  else if (url.includes('facebook.com'))       icon.className = 'bi bi-facebook';
  else if (url.includes('youtube.com') || url.includes('youtu.be')) icon.className = 'bi bi-youtube';
  else if (url.includes('tiktok.com'))         icon.className = 'bi bi-tiktok';
  else if (url.includes('whatsapp.com') || url.includes('wa.me')) icon.className = 'bi bi-whatsapp';
  else if (url.includes('linkedin.com'))       icon.className = 'bi bi-linkedin';
  else if (url.includes('github.com'))         icon.className = 'bi bi-github';
  else if (url.includes('spotify.com'))        icon.className = 'bi bi-spotify';
  else if (url.includes('twitch.tv'))          icon.className = 'bi bi-twitch';
  else if (url.includes('threads.net'))        icon.className = 'bi bi-threads';
  else if (url.includes('t.me') || url.includes('telegram.org')) icon.className = 'bi bi-telegram';
  else if (url.includes('snapchat.com'))       icon.className = 'bi bi-snapchat';
  else if (url.includes('pinterest.com'))      icon.className = 'bi bi-pinterest';
  else if (url.includes('mailto:'))            icon.className = 'bi bi-envelope-at-fill';
  // else: mantém bi-link-45deg como fallback genérico
});

whatsapp_floating.css:
.whatsapp-widget-container { position: fixed; bottom: 25px; right: 25px; z-index: 9999; }
