@media (max-width: 768px) { .whatsapp-btn { width: 55px; height: 55px; } }

web_share_api.javascript:
const btnShare = document.getElementById('btnShare');
let isSharing = false;

if (btnShare) {
  btnShare.addEventListener('click', async () => {
    if (isSharing) return; // Trava anti-spam

    if (navigator.share) {
      try {
        await navigator.share({
          title: document.title,
          text: 'Confere os meus links!',
          url: window.location.href
        });
      } catch (err) {
        // Usuário cancelou — não é erro real
        console.log('Partilha cancelada.');
      }
    } else {
      // Fallback: copia URL para clipboard (desktop)
      isSharing = true;
      navigator.clipboard.writeText(window.location.href);
      btnShare.innerHTML = '<i class="bi bi-check2-circle me-2"></i> Copiado!';
      setTimeout(() => {
        btnShare.innerHTML = '<i class="bi bi-share-fill me-2"></i> Partilhar';
        isSharing = false; // Liberta a trava após feedback
      }, 2500);
    }
  });
}

